var import_obsidian12 = require("obsidian");

// src/utils/debounce.ts
init_esbuild_polyfills();
function debounce(fn, delayMs) {
  let timeout = null;
  return (...args) => {
    if (timeout) {
      clearTimeout(timeout);
    }
    timeout = setTimeout(() => fn(...args), delayMs);
  };
}

// src/vault/watcher.ts
var VaultWatcher = class {
  constructor(vault, orchestrator, settings) {
    this.vault = vault;
    this.orchestrator = orchestrator;
    this.settings = settings;
    this.debouncedQueue = debounce((path) => this.orchestrator.queueFileSync(path), settings.debounceDelayMs);
  }
  register(plugin) {
    plugin.registerEvent(
      this.vault.on("create", (file) => {
        if (file instanceof import_obsidian12.TFile && this.settings.syncOnSave) {
          this.debouncedQueue(file.path);
        }
      })
    );
    plugin.registerEvent(
      this.vault.on("modify", (file) => {
        if (file instanceof import_obsidian12.TFile && this.settings.syncOnSave) {
          this.debouncedQueue(file.path);
        }
      })
    );
    plugin.registerEvent(
      this.vault.on("delete", (file) => {
        if (file instanceof import_obsidian12.TFile && this.settings.syncOnSave) {
          this.orchestrator.queueFileDelete(file.path);
        }
      })
    );
    plugin.registerEvent(
      this.vault.on("rename", (file, oldPath) => {
        if (file instanceof import_obsidian12.TFile && this.settings.syncOnSave) {
          this.orchestrator.queueFileRename(oldPath, file.path);
        }
      })
    );
  }
};

